-- MySQL 8.0 / root 실행. 공유 서버에서는 교육용 공통 계정의 접근 권한이 누적된다.
CREATE DATABASE IF NOT EXISTS mysqlragdb0 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE USER IF NOT EXISTS 'ragid'@'%' IDENTIFIED BY 'ragpw';
GRANT ALL PRIVILEGES ON mysqlragdb0.* TO 'ragid'@'%';
FLUSH PRIVILEGES;
USE mysqlragdb0;
CREATE TABLE IF NOT EXISTS customers (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,category VARCHAR(60) NOT NULL,price DECIMAL(12,2) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,CHECK (price>=0));
CREATE TABLE IF NOT EXISTS orders (id BIGINT PRIMARY KEY AUTO_INCREMENT,customer_id BIGINT NOT NULL,ordered_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,status ENUM('PAID','DELIVERED','CANCELLED','REFUNDED') NOT NULL,FOREIGN KEY(customer_id) REFERENCES customers(id),INDEX(customer_id,ordered_at));
CREATE TABLE IF NOT EXISTS order_items (id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,product_id BIGINT NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(12,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(product_id) REFERENCES products(id),CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS reviews (id BIGINT PRIMARY KEY AUTO_INCREMENT,customer_id BIGINT NOT NULL,product_id BIGINT NOT NULL,rating TINYINT NOT NULL,content TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(product_id) REFERENCES products(id),CHECK(rating BETWEEN 1 AND 5));
CREATE TABLE IF NOT EXISTS complaints (id BIGINT PRIMARY KEY AUTO_INCREMENT,customer_id BIGINT NOT NULL,order_id BIGINT NULL,category VARCHAR(50) NOT NULL,content TEXT NOT NULL,status ENUM('OPEN','IN_PROGRESS','RESOLVED') NOT NULL DEFAULT 'OPEN',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE IF NOT EXISTS source_documents (id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(255) NOT NULL,source_type VARCHAR(20) NOT NULL,content LONGTEXT NOT NULL,metadata_json JSON,index_status ENUM('PENDING','READY','FAILED') NOT NULL DEFAULT 'PENDING',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS document_chunks (id BIGINT PRIMARY KEY AUTO_INCREMENT,document_id BIGINT NOT NULL,chunk_no INT NOT NULL,content TEXT NOT NULL,UNIQUE(document_id,chunk_no),FOREIGN KEY(document_id) REFERENCES source_documents(id));
CREATE TABLE IF NOT EXISTS external_articles (id BIGINT PRIMARY KEY AUTO_INCREMENT,source_id VARCHAR(100) NOT NULL UNIQUE,title VARCHAR(200) NOT NULL,content TEXT NOT NULL,raw_json JSON NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS complaint_replies (id BIGINT PRIMARY KEY AUTO_INCREMENT,complaint_id BIGINT NOT NULL,manual_document_id BIGINT NULL,content TEXT NOT NULL,status ENUM('DRAFT','APPROVED','SENT') NOT NULL DEFAULT 'DRAFT',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(complaint_id) REFERENCES complaints(id),FOREIGN KEY(manual_document_id) REFERENCES source_documents(id));
CREATE TABLE IF NOT EXISTS answer_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT,customer_id BIGINT NULL,question TEXT NOT NULL,answer LONGTEXT NOT NULL,source_json JSON,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE IF NOT EXISTS recommendation_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT,customer_id BIGINT NOT NULL,answer LONGTEXT NOT NULL,evidence_json JSON NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id));
